.search-budgets{display:flex;align-items:center;gap:5px;margin:-4px 0 15px;font-size:9px;color:#6e7e90}.search-budgets>span{margin-right:8px}.search-budgets button{font-size:9px;background:none;border:1px solid transparent;color:#748190;border-radius:3px;padding:4px 8px}.search-budgets button.active{border-color:#8e805844;color:#baa986;background:#b8a37308}
.search-plan{margin-top:14px;padding:16px 18px;border:1px solid #343d44;border-radius:7px;background:#151c23}.search-plan>header{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.search-plan strong{font-size:12px;font-weight:500;color:#c5c2af}.search-plan header>span{font-size:10px;color:#7b8998}.portfolio{display:flex;align-items:center;gap:15px;font-size:10px;color:#98a5af;margin:0 0 14px}.portfolio>b{color:#c4b58c;font-size:17px;font-weight:500}.portfolio>small{font-size:9px;color:#5f7184}.buy-now{display:flex;align-items:center;gap:5px;margin-left:auto}.buy-now img{width:25px;height:25px;border:1px solid #8b7d62}.search-goals{display:flex;gap:14px}.search-goal{flex:1;display:flex;align-items:center;gap:10px;padding:11px;background:#10171e;border-radius:4px;border:1px solid #2e3842;min-width:0}.search-goal>span{display:flex;gap:6px}.search-target{display:flex;flex-direction:column;align-items:center;gap:4px}.search-target img{width:29px;height:29px;border:1px solid #656b70;border-radius:3px}.search-target small{font-size:8px;color:#778a9c}.search-goal>b{font-size:13px;font-weight:500;color:#a9b7a8;white-space:nowrap}.search-goal>small{font-size:9px;color:#738293;margin-left:auto}
